#!/bin/sh
# Written by the Workshop at run time from the actual measured input and the declared knowledge
# `numeric-strict-sum.md`: sum every measured value strictly greater than LIMIT, and write the
# integer sum alone to result.txt.
#
#   $1 = the Campaign workspace (holds flow/measured.txt, receives result.txt)
#   $2 = LIMIT
set -eu

workspace=${1:?the Campaign workspace}
limit=${2:?the LIMIT threshold}

awk -v limit="$limit" '
  /^[0-9]+$/ { if ($0 + 0 > limit + 0) total += $0 + 0 }
  END { printf "%d\n", total + 0 }
' "$workspace/flow/measured.txt" > "$workspace/result.txt"

